def test_epoch_rollover_uses_bounded_transition_heartbeat(monkeypatch):
    expected = ([{"role": "user", "content": "fresh"}], {}, {"current": None})
    captured: dict = {}

    monkeypatch.setattr(
        runner,
        "_roll_autonomous_campaign_epoch_unobserved",
        lambda *_args, **_kwargs: expected,
    )

    def run_epoch_transition(operation, **kwargs):
        captured.update(kwargs)
        return operation()

    monkeypatch.setattr(runner.transition_visibility, "run_epoch_transition", run_epoch_transition)
    result = runner._roll_autonomous_campaign_epoch(
        object(),
        [],
        {},
        {},
        {
            "campaign_epoch": 3,
            "current_queue_assignment": {"target_symbol": "demo"},
        },
        {},
        reason="route-no-progress",
        cycle=4,
    )

    assert result == expected
    assert captured["delay_s"] == 5.0
    assert captured["heartbeat_s"] == 30.0
    assert captured["previous_epoch"] == 3
    assert captured["target_symbol"] == "demo"
    assert captured["reason"] == "route-no-progress"


class _ManagedRunAgentStub:
    """Minimal managed-run contract surface (see agent/runtime/managed_run.py) for runner tests.

    native_runner stages guidance through the agent's stage/set/clear_tool_result_appendix methods.
    These mirror AIAgent's semantics (accumulate / replace / discard) over the same backing
    ``_post_tool_result_appendix`` attribute the tests inspect, so a stub honestly satisfies the
    contract rather than exposing only a raw attribute.
    """

    def stage_tool_result_appendix(self, text: str) -> None:
        text = str(text or "").strip()
        if not text:
            return
        previous = str(getattr(self, "_post_tool_result_appendix", "") or "").strip()
        self._post_tool_result_appendix = f"{previous}\n\n{text}".strip() if previous else text

    def set_tool_result_appendix(self, text: str) -> None:
        text = str(text or "").strip()
        if text:
            self._post_tool_result_appendix = text
        else:
            self.clear_tool_result_appendix()

    def clear_tool_result_appendix(self) -> None:
        if hasattr(self, "_post_tool_result_appendix"):
            delattr(self, "_post_tool_result_appendix")


class _FakeAgent(_ManagedRunAgentStub):
    compression_enabled = True

    def __init__(self):
        self.context_compressor = _FakeCompressor()
        self._checkpoint_mgr = _FakeCheckpointManager()


def test_foreground_checked_helper_is_retained_before_handoff(monkeypatch, tmp_path):
    active = tmp_path / "Demo.lean"
    active.write_text("theorem demo : True := by\n  sorry\n", encoding="utf-8")
    agent = _ManagedRunAgentStub()
    agent._managed_autonomy_state = {
        "campaign_id": "campaign",
        "current_queue_assignment": {
            "target_symbol": "demo",
            "active_file": str(active),
        },
    }
    monkeypatch.setattr(
        runner.research_helper_candidate_priority.plan_state,
        "plan_state_enabled",
        lambda: False,
    )
    events = []
    monkeypatch.setattr(
        runner, "_record_agent_activity", lambda *args, **kwargs: events.append(kwargs)
    )
    declaration = "private lemma checked_helper : True := by\n  trivial"
    arguments = {
        "action": "check_helper",
        "file_path": str(active),
        "theorem_id": "demo",
        "replacement": declaration,
    }
    result = json.dumps(
        {
            "success": True,
            "ok": True,
            "valid_without_sorry": True,
            "has_errors": False,
            "has_sorry": False,
            "verification_scope": "helper_candidate",
            "replacement_matches_target": False,
            "replacement_declarations": ["checked_helper"],
        }
    )

    record = runner._retain_foreground_checked_helper(
        agent, "lean_incremental_check", arguments, result
    )

    assert record is not None
    assert record.helper_name == "checked_helper"
    assert events[0]["candidate_id"] == record.candidate_id
    assert "durably retained" in agent._post_tool_result_appendix


