def test_search_synthesis_reservation_bounds_construction_source_inspection(monkeypatch, tmp_path):
    """Reserve a correction response before yielding a source-only construction turn."""
    active = tmp_path / "Main.lean"
    active.write_text("theorem demo : True := by\n  sorry\n", encoding="utf-8")
    events: list[tuple[tuple, dict]] = []

    class _Agent(_ManagedRunAgentStub):
        def __init__(self):
            self.session_id = "construction-read-loop"
            self._session_messages = []
            self._managed_autonomy_state = {
                "current_cycle": 9,
                "current_queue_assignment": {
                    "target_symbol": "demo",
                    "active_file": str(active),
                },
                "search_progress": {
                    "target_symbol": "demo",
                    "active_file": str(active),
                    "search_count": 12,
                    "hard_route_requested": True,
                    "synthesis_grace_pending": True,
                },
            }
            self.interrupt_messages: list[str | None] = []

        def is_interrupted(self):
            return False

        def interrupt(self, message=None):
            self.interrupt_messages.append(message)

    monkeypatch.setattr(runner, "_single_queue_item_turn_enabled", lambda: True)
    monkeypatch.setattr(runner, "_construction_source_inspection_hard_limit", lambda: 3)
    monkeypatch.setattr(
        runner, "_record_activity", lambda *args, **kwargs: events.append((args, kwargs))
    )
    agent = _Agent()

    for pattern in ("top_sum_bound", "alternating_odd_bound", "opponentClaims"):
        runner._handle_managed_tool_result(
            agent,
            "search_files",
            {"path": str(active), "pattern": pattern, "output_mode": "content"},
            json.dumps({"success": True}),
        )

    tracker = agent._managed_autonomy_state["search_progress"]
    assert tracker["construction_source_inspection_count"] == 3
    assert tracker["construction_source_inspection_boundary"] is True
    assert "prover_requested_route" not in agent._managed_autonomy_state
    assert not bool(getattr(agent, "_managed_step_boundary_closed", False))
    assert agent.interrupt_messages == []
    assert any(event[0][0] == "construction-source-inspection-boundary" for event in events)

    blocked = runner._managed_pre_tool_call(
        agent,
        "read_file",
        {"path": str(active), "offset": 1, "limit": 40},
    )
    assert blocked is not None
    payload = json.loads(blocked)
    assert payload["status"] == "construction_synthesis_required"
    assert payload["provider_called"] is False
    assert tracker["construction_source_inspection_count"] == 3

    runner._handle_managed_tool_result(
        agent,
        "read_file",
        {"path": str(active), "offset": 1, "limit": 40},
        blocked,
    )
    assert not bool(getattr(agent, "_managed_step_boundary_closed", False))
    assert agent.interrupt_messages == []

    blocked_again = runner._managed_pre_tool_call(
        agent,
        "lean_outline",
        {"file_path": str(active), "symbol": "demo"},
    )
    assert blocked_again is not None
    runner._handle_managed_tool_result(
        agent,
        "lean_outline",
        {"file_path": str(active), "symbol": "demo"},
        blocked_again,
    )
    assert agent._managed_autonomy_state["prover_requested_route"]["route"] == "plan"
    assert agent._managed_step_boundary_closed is True
    assert agent.interrupt_messages == [runner.WORKFLOW_STEP_BOUNDARY_INTERRUPT]
    tracker = agent._managed_autonomy_state["search_progress"]
    assert tracker["construction_source_window_reset_pending"] is True

    runner._prepare_managed_turn_state(agent, agent._managed_autonomy_state)
    refreshed_tracker = agent._managed_autonomy_state["search_progress"]
    assert "construction_source_inspection_boundary" not in refreshed_tracker
    assert "construction_source_inspection_count" not in refreshed_tracker


