def test_scope_entry_proved_split_helper_preempts_replanning_parent(monkeypatch, tmp_path):
    """A proved decomposition child must get one parent-assembly turn."""
    active = tmp_path / "Main.lean"
    active.write_text(
        "private lemma bridge : True := by\n"
        "  trivial\n\n"
        "theorem result : True := by\n"
        "  sorry\n",
        encoding="utf-8",
    )
    active_file = str(active.resolve())
    target_id = runner.plan_state.node_id_for("result", active_file)
    helper_id = runner.plan_state.node_id_for("bridge", active_file)
    blueprint = runner.plan_state.Blueprint(
        nodes=(
            runner.plan_state.GraphNode(
                id=target_id,
                name="result",
                file=active_file,
                statement="theorem result : True := by\n  sorry",
                status="proving",
                generated_by="queue-sync",
            ),
            runner.plan_state.GraphNode(
                id=helper_id,
                kind="lemma",
                name="bridge",
                file=active_file,
                statement="private lemma bridge : True := by\n  trivial",
                status="proved",
                generated_by="decomposer",
            ),
        ),
        edges=(
            runner.plan_state.GraphEdge(helper_id, target_id, "split_of"),
            runner.plan_state.GraphEdge(target_id, helper_id, "depends_on"),
        ),
    )
    summary = {
        "queue_manager_state": {
            "theorem_outcomes": {
                f"{active_file}::bridge": {
                    "target_symbol": "bridge",
                    "active_file": active_file,
                    "status": "solved",
                }
            }
        }
    }
    state = {
        "current_queue_assignment": {
            "target_symbol": "result",
            "active_file": active_file,
        },
        "prover_requested_route": {
            "route": "plan",
            "target_symbol": "result",
            "active_file": active_file,
        },
    }
    monkeypatch.setenv("LEANFLOW_PROJECT_ROOT", str(tmp_path))
    monkeypatch.setenv("LEANFLOW_PLAN_STATE", "1")
    monkeypatch.setattr(runner.research_mode, "research_mode_enabled", lambda: True)
    monkeypatch.setattr(runner, "_maybe_sync_plan_state", lambda *_args, **_kwargs: None)
    monkeypatch.setattr(runner.plan_state, "load_blueprint", lambda: blueprint)
    monkeypatch.setattr(runner.plan_state, "load_summary", lambda: summary)
    monkeypatch.setattr(
        runner,
        "_maintain_research_portfolio",
        lambda *_args, **_kwargs: pytest.fail("proved helper handback launched research"),
    )
    monkeypatch.setattr(
        runner,
        "_orchestrator_consult",
        lambda *_args, **_kwargs: pytest.fail("proved helper handback replanned parent"),
    )

    prompt = runner._research_scope_entry_setup(
        "",
        state,
        {
            "target_symbol": "result",
            "active_file": active_file,
            "current_queue_item": {"label": "result"},
        },
        agent=object(),
        apply_route=True,
    )

    assert "[LEANFLOW PROVED-HELPER PARENT HANDBACK]" in prompt
    assert "`bridge`" in prompt
    assert state["orchestrator_scope_entered"] is True
    assert "prover_requested_route" not in state


def test_parent_rechecks_checked_helper_before_orchestrator_and_fences_broad_search(
    monkeypatch, tmp_path
):
    """Turn a staged helper into the immediate exact integration task."""
    monkeypatch.setenv("LEANFLOW_PROJECT_ROOT", str(tmp_path))
    monkeypatch.setattr(runner.research_mode, "research_mode_enabled", lambda: True)
    monkeypatch.setattr(runner, "_maybe_sync_plan_state", lambda *_args, **_kwargs: None)
    monkeypatch.setattr(runner, "_maybe_statement_fidelity_audit", lambda *_args: None)
    monkeypatch.setattr(
        runner,
        "_migrate_research_findings_for_assignment",
        lambda *_args, **_kwargs: {},
    )
    monkeypatch.setattr(runner, "_maintain_research_portfolio", lambda *_args: None)
    monkeypatch.setattr(runner, "_take_research_findings_prompt", lambda *_args: "")
    monkeypatch.setattr(
        runner.research_helper_candidate_priority.plan_state,
        "plan_state_enabled",
        lambda: False,
    )
    active = tmp_path / "Main.lean"
    active.write_text("theorem demo : True := by\n  sorry\n", encoding="utf-8")
    declaration = "private lemma checked_family (n : Nat) : True := by\n  trivial"
    declaration_hash = runner.hashlib.sha256(declaration.encode("utf-8")).hexdigest()
    finding = {
        "job_id": "campaign.orchestrator.em-checked",
        "target_symbol": "demo",
        "active_file": str(active),
        "deliverable": {
            "checked_helper_status": "worker_checked_parent_recheck_required",
            "parent_recheck_required": True,
            "checked_helpers": [
                {
                    "active_file": str(active),
                    "anchor_target_symbol": "demo",
                    "declaration": declaration,
                    "declaration_sha256": declaration_hash,
                    "parent_recheck_required": True,
                    "worker_check": {
                        "tool": "lean_incremental_check",
                        "action": "check_helper",
                        "valid_without_sorry": True,
                        "has_errors": False,
                        "has_sorry": False,
                        "verification_scope": "helper_candidate",
                        "replacement_matches_target": False,
                        "replacement_declarations": ["checked_family"],
                    },
                }
            ],
        },
    }
    state = {
        "campaign_id": "campaign",
        "current_queue_assignment": {
            "target_symbol": "demo",
            "active_file": str(active),
        },
    }
    runner.research_helper_candidate_priority.remember_from_findings(
        state,
        (finding,),
        campaign_id="campaign",
        target_symbol="demo",
        active_file=str(active),
    )
    pending_before_recheck = runner.research_helper_candidate_priority.load(state)
    assert pending_before_recheck is not None
    assert (
        pending_before_recheck.state == runner.research_helper_candidate_priority.AWAITING_RECHECK
    )

    class _PendingAgent(_ManagedRunAgentStub):
        _managed_autonomy_state = state

        def is_interrupted(self):
            return False

        def interrupt(self, reason):
            self._interrupt_reason = reason

    awaiting_recheck_block = json.loads(
        runner._managed_pre_tool_call(
            _PendingAgent(),
            "lean_search",
            {"query": "another route", "file_path": str(active)},
        )
    )
    assert awaiting_recheck_block["status"] == "checked_helper_parent_recheck_required"
    assert awaiting_recheck_block["helper_symbol"] == "checked_family"
    assert awaiting_recheck_block["preserved_declaration"] == declaration
    unrelated_helper_block = runner._managed_pre_tool_call(
        _PendingAgent(),
        "lean_incremental_check",
        {
            "action": "check_helper",
            "file_path": str(active),
            "theorem_id": "demo",
            "replacement": "private lemma unrelated : True := by\n  trivial",
        },
    )
    assert unrelated_helper_block is None
    target_probe = runner._managed_pre_tool_call(
        _PendingAgent(),
        "lean_incremental_check",
        {
            "action": "check_target",
            "file_path": str(active),
            "theorem_id": "demo",
            "replacement": "theorem demo : True := by\n  trivial",
        },
    )
    assert target_probe is None
    boundary_agent = _PendingAgent()
    reformatted_declaration = (
        "private lemma checked_family\n" "    (n : Nat) :\n" "    True := by\n" "  trivial"
    )
    parent_boundary = json.loads(
        runner._managed_pre_tool_call(
            boundary_agent,
            "apply_verified_patch",
            {
                "path": str(active),
                "theorem_id": "demo",
                "patch": (
                    "*** Begin Patch\n"
                    f"*** Update File: {active}\n"
                    "@@\n"
                    f"+{reformatted_declaration.replace(chr(10), chr(10) + '+')}\n"
                    "+\n"
                    " theorem demo : True := by\n"
                    "*** End Patch\n"
                ),
            },
        )
    )
    assert parent_boundary["status"] == "checked_helper_parent_recheck_pending"
    assert parent_boundary["patch_applied"] is False
    assert parent_boundary["lean_started"] is False
    assert parent_boundary["preserved_declaration"] == declaration
    assert boundary_agent._managed_step_boundary_closed is True
    assert (
        state[runner._RESEARCH_HELPER_RECHECK_BOUNDARY_KEY] == pending_before_recheck.candidate_id
    )
    checks = []
    admission_order: list[str] = []
    monkeypatch.setattr(
        runner.helper_integration_admission,
        "ensure",
        lambda *_args, **_kwargs: admission_order.append("continuous-helper-reservation")
        or SimpleNamespace(),
    )
    monkeypatch.setattr(
        runner.helper_integration_admission,
        "release",
        lambda *_args, **_kwargs: False,
    )
    monkeypatch.setattr(
        runner,
        "_record_activity",
        lambda event, *_args, **_kwargs: (
            admission_order.append(event)
            if event == "research-helper-parent-recheck-accepted"
            else None
        ),
    )

    monkeypatch.setattr(
        runner.scope_entry_admission,
        "arm",
        lambda *_args, **kwargs: admission_order.append(str(kwargs.get("reason", "scope-entry")))
        or SimpleNamespace(to_dict=lambda: {"marker_path": "lease"}),
    )

    def check(**kwargs):
        admission_order.append("parent-check")
        checks.append(kwargs)
        return {
            "success": True,
            "ok": True,
            "action": "check_helper",
            "valid_without_sorry": True,
            "has_errors": False,
            "has_sorry": False,
            "timed_out": False,
            "verification_scope": "helper_candidate",
            "replacement_matches_target": False,
            "replacement_declarations": ["checked_family"],
            "axiom_profile_requested": True,
            "axiom_profile_checked": True,
            "axiom_profile_axioms": ["Classical.choice"],
            "axiom_profile_blockers": [],
            "axiom_profile_error": "",
        }

    monkeypatch.setattr(runner, "lean_incremental_check", check)

    @contextlib.contextmanager
    def parent_transaction(*_args):
        admission_order.append("parent-transaction-enter")
        try:
            yield
        finally:
            admission_order.append("parent-transaction-exit")

    monkeypatch.setattr(
        runner.verification_transaction,
        "parent_lean_verification_transaction",
        parent_transaction,
    )
    monkeypatch.setattr(
        runner,
        "_orchestrator_consult",
        lambda *_args, **_kwargs: pytest.fail("orchestrator ran before helper integration"),
    )

    state["prover_requested_route"] = {
        "route": "plan",
        "target_symbol": "demo",
        "active_file": str(active),
        "reason": "existing requested route must survive the promised parent check",
    }
    prompt = runner._consume_research_helper_parent_recheck_boundary(
        state,
        {"target_symbol": "demo", "active_file": str(active)},
        agent=SimpleNamespace(),
    )

    assert admission_order == [
        "pending parent helper recheck for checked_family",
        "parent-transaction-enter",
        "parent-check",
        "continuous-helper-reservation",
        "parent-transaction-exit",
        "research-helper-parent-recheck-accepted",
    ]
    assert checks[0]["action"] == "check_helper"
    assert checks[0]["replacement"] == declaration
    pending = runner.research_helper_candidate_priority.load(state)
    assert pending is not None and pending.ready
    assert pending.parent_recheck_axioms == ("Classical.choice",)
    assert pending.expected_integrated_source_revision_sha256
    assert runner.research_helper_candidate_priority.parent_recheck_evidence_authenticated(pending)
    assert declaration in prompt
    assert state["prover_requested_route"]["route"] == "plan"
    assert runner._RESEARCH_HELPER_RECHECK_BOUNDARY_KEY not in state

    class _Agent(_ManagedRunAgentStub):
        _managed_autonomy_state = state

        def is_interrupted(self):
            return False

    blocked = json.loads(
        runner._managed_pre_tool_call(
            _Agent(),
            "lean_search",
            {"query": "another route", "file_path": str(active)},
        )
    )
    assert blocked["status"] == "checked_helper_integration_required"
    assert blocked["helper_symbol"] == "checked_family"
    assert blocked["preserved_declaration"] == declaration
    exact_patch = {
        "path": str(active),
        "old_string": "theorem demo : True := by\n  sorry",
        "new_string": declaration + "\n\ntheorem demo : True := by\n  sorry",
    }
    removal_disguise = {
        "path": str(active),
        "old_string": declaration,
        "new_string": "-- unrelated edit",
    }
    disguised = json.loads(runner._managed_pre_tool_call(_Agent(), "patch", removal_disguise))
    assert disguised["status"] == "checked_helper_integration_required"
    blocked_unverified = json.loads(runner._managed_pre_tool_call(_Agent(), "patch", exact_patch))
    assert blocked_unverified["status"] == "checked_helper_verified_patch_required"
    different_declaration = "private lemma other_family : True := by\n  trivial"
    mismatched_helper_patch = {
        "path": str(active),
        "theorem_id": "demo",
        "patch": (
            "*** Begin Patch\n"
            f"*** Update File: {active}\n"
            "@@\n"
            f"+{different_declaration.replace(chr(10), chr(10) + '+')}\n"
            "+\n"
            " theorem demo : True := by\n"
            "*** End Patch\n"
        ),
    }
    mismatched = json.loads(
        runner._managed_pre_tool_call(
            _Agent(),
            "apply_verified_patch",
            mismatched_helper_patch,
        )
    )
    assert mismatched["status"] == "checked_helper_verified_patch_mismatch"
    assert mismatched["helper_symbol"] == "checked_family"
    assert mismatched["patch_applied"] is False
    assert mismatched["lean_started"] is False
    assert "other_family" in mismatched_helper_patch["patch"]
    verified_patch = {
        "path": str(active),
        # Models may omit theorem_id for a helper-only edit.
        "patch": "stale model-authored patch replaced by manager authority",
    }
    assert runner._managed_pre_tool_call(_Agent(), "apply_verified_patch", verified_patch) is None
    assert verified_patch["theorem_id"] == "demo"
    assert verified_patch["_leanflow_verified_edit_authority"]
    assert verified_patch["patch"] == (
        runner.parent_helper_verification_reuse.exact_integrated_source_patch(
            active.read_text(encoding="utf-8"),
            runner.research_helper_candidate_priority.load(state),
            path=str(active),
        )
    )
    assert runner._managed_pre_tool_call(_Agent(), "apply_verified_patch", verified_patch) is None
    assert (
        runner.research_helper_candidate_priority.load(state).integration_attempts
        == runner.research_helper_candidate_priority.MAX_INTEGRATION_ATTEMPTS
    )
    # Two failed exact insertion preflights exhaust only the tool fence, not the
    # durable candidate. Research can continue while the helper stays pending.
    assert (
        runner._managed_pre_tool_call(
            _Agent(),
            "lean_search",
            {"query": "different route", "file_path": str(active)},
        )
        is None
    )
    assert runner.research_helper_candidate_priority.load(state) is not None


def test_helper_pretool_guard_rejects_same_name_source_collision(monkeypatch, tmp_path):
    """Never allow a ready insertion candidate to duplicate a current declaration."""
    monkeypatch.setattr(
        runner.research_helper_candidate_priority.plan_state,
        "plan_state_enabled",
        lambda: False,
    )
    active = tmp_path / "Main.lean"
    target = "theorem demo : True := by\n  sorry"
    active.write_text(target + "\n", encoding="utf-8")
    declaration = "private lemma checked_family : True := by\n  trivial"
    finding = {
        "job_id": "campaign.orchestrator.ds-collision",
        "target_symbol": "demo",
        "active_file": str(active),
        "semantic_novelty": {
            "version": 9,
            "classification": "novel",
            "progress_anchor_eligible": True,
            "progress_anchor_reason": "new_mathematical_semantics",
            "has_checked_helper": True,
        },
        "deliverable": {
            "checked_helper_route_disposition": "advance_current_route",
            "checked_helper_dependency_advanced": "demo dependency",
            "checked_helper_status": "worker_checked_parent_recheck_required",
            "parent_recheck_required": True,
            "checked_helpers": [
                {
                    "active_file": str(active),
                    "anchor_target_symbol": "demo",
                    "declaration": declaration,
                    "declaration_sha256": runner.hashlib.sha256(declaration.encode()).hexdigest(),
                    "parent_recheck_required": True,
                    "worker_check": {
                        "tool": "lean_incremental_check",
                        "action": "check_helper",
                        "valid_without_sorry": True,
                        "has_errors": False,
                        "has_sorry": False,
                        "verification_scope": "helper_candidate",
                        "replacement_matches_target": False,
                        "replacement_declarations": ["checked_family"],
                    },
                }
            ],
        },
    }
    state = {
        "campaign_id": "campaign",
        "current_queue_assignment": {
            "target_symbol": "demo",
            "active_file": str(active),
        },
    }
    pending = runner.research_helper_candidate_priority.remember_from_findings(
        state,
        (finding,),
        campaign_id="campaign",
        target_symbol="demo",
        active_file=str(active),
    )
    assert pending is not None
    ready = runner.research_helper_candidate_priority.mark_parent_recheck(
        state,
        candidate_id=pending.candidate_id,
        status="accepted",
        source_revision_sha256=runner.research_helper_candidate_priority.source_revision_sha256(
            str(active)
        ),
        detail="test parent check",
    )
    assert ready is not None and ready.integration_fence_active
    source = "private lemma checked_family : False := by\n  sorry\n\n" + target + "\n"
    active.write_text(source, encoding="utf-8")

    agent = _ManagedRunAgentStub()
    agent._managed_autonomy_state = state
    result = runner._managed_pre_tool_call(
        agent,
        "patch",
        {
            "path": str(active),
            "old_string": target,
            "new_string": declaration + "\n\n" + target,
        },
    )

    assert result is not None
    payload = json.loads(result)
    assert payload["status"] == "duplicate_declaration_rejected"
    assert payload["duplicate_declarations"] == ["checked_family"]
    assert payload["lean_started"] is False
    assert runner.research_helper_candidate_priority.load(state) is None
    assert active.read_text(encoding="utf-8") == source


